// Rule L3b: a value call is the function's first output and leaves the others out; 2.0 wants every `out` passed.
/// @asset Path(Game, "Functions/MF_MgResultAndMore")
extern float3 MF_MgResultAndMore(float3 Colour, out float Extra);

/// @name DreamShaderTests/Migrate/M_MgAbsentOuts
export void M_MgAbsentOuts(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float MF_MgResultAndMore_Extra;
    Color = MF_MgResultAndMore(float3(1.0, 0.5, 0.25), Extra = MF_MgResultAndMore_Extra) * 2.0;
    Base.EmissiveColor = Color;
}
